Aşağıdaki kodun sonunda sonuc değişkeninin değeri kaç olur?
int ikiKat(int x) {
    return 2 * x;
}
int artir(int x) {
    return x + 1;
}
int sonuc = ikiKat(artir(3));

Aşağıdaki C kodu hangi çıktıyı üretir?

int x = 2;
x = x + 3;
printf("%d", x);

Aşağıdaki C kodu hangi çıktıyı üretir?

int f(int x) {
    if (x % 2 == 0) return x / 2;
    return x * 3;
}

printf("%d", f(5) + f(8));

Aşağıdaki C kodunda printf hangi değeri yazar?

int a[4] = {2, 4, 6, 8};
int *p = a;
printf("%d", *(p + 3));

